-- PT106-S3-Q19. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT106-S3-Q19$batch04$ AND q.stimulus=$batch04$On a certain day, nine scheduled flights on Swift Airlines were canceled. Ordinarily, a cancellation is due to mechanical problems with the airplane scheduled for a certain flight. However, since it is unlikely that Swift would have mechanical problems with more than one or two airplanes on a single day, some of the nine cancellations were probably due to something else.$batch04$ AND q.prompt=$batch04$The argument depends on which one of the following assumptions?$batch04$ AND q.correct_choice=$batch04$A$batch04$) THEN RAISE EXCEPTION 'Question changed: PT106-S3-Q19'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT106-S3-Q19$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT106-S3-Q19'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT106-S3-Q19$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$Some of the nine cancellations were probably due to something other than mechanical problems.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$Nine Swift flights were canceled in one day. Cancellations are usually caused by mechanical problems with the plane scheduled for the flight. Swift is unlikely to have mechanical problems with more than one or two planes in a day.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The argument switches from nine *flights* to one or two *planes*. A single plane often flies several routes in a day. If one or two broken planes were scheduled for all nine flights, mechanical problems explain every cancellation.$batch04$), (3, $batch04$Goal$batch04$, $batch04$The nine flights were scheduled on more than one or two planes.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT106-S3-Q19$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Negate it: only one or two planes were scheduled for all nine flights. Then one or two mechanical problems could account for every cancellation, and there is no reason to suspect another cause.$batch04$), ($batch04$B$batch04$, $batch04$How Swift compares with other airlines does not matter. The argument is about Swift on this day.$batch04$), ($batch04$C$batch04$, $batch04$Flight length plays no role in the argument.$batch04$), ($batch04$D$batch04$, $batch04$Past cancellation records do not affect what caused these nine.$batch04$), ($batch04$E$batch04$, $batch04$Where the planes are based does not affect how many there were.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT106-S3-Q19$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
